contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to send into c by using c.sendMoney (owner-only) which performs a low-level call
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure this test contract has enough balance to perform the sendMoney call
        require(depositAmount <= address(this).balance);

        // observe contract balance before any action
        uint beforeBalance = address(c).balance;

        // As deployer/owner of C (per problem statement), this contract may call owner-only methods.
        // Use sendMoney to move Ether into c (it uses low-level call to target and will credit c's balance if value>0)
        c.sendMoney(address(c), depositAmount); if (__ESBMC_reverted()) return;

        // observe balance after sending
        uint midBalance = address(c).balance;

        // record this contract's balance before withdrawAll
        uint ownerBefore = address(this).balance;

        // call withdrawAll (owner-only) which should transfer entire contract balance to msg.sender (this contract)
        c.withdrawAll(); if (__ESBMC_reverted()) return;

        // observe balances after withdrawAll
        uint finalContractBalance = address(c).balance;
        uint ownerAfter = address(this).balance;

        // The general rule to assert:
        // withdrawAll (called by owner) always drains C to zero, and the owner's balance increases exactly by the drained amount.
        // Expressed: finalContractBalance == 0 and ownerAfter == ownerBefore + midBalance
        assert(finalContractBalance == 0 && ownerAfter == ownerBefore + midBalance);
    }

    // accept Ether when withdrawAll transfers funds to this contract
    receive() external payable {}
}

