// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount <= address(this).balance);
        uint beforeBalance = address(c).balance;
        try c.sendMoney(address(c), depositAmount) {} catch { return; }
        uint midBalance = address(c).balance;
        uint ownerBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint finalContractBalance = address(c).balance;
        uint ownerAfter = address(this).balance;
        assertTrue(finalContractBalance == 0 && ownerAfter == ownerBefore + midBalance);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
